'use strict';
let MatchArchiveIndex=null,archiveMatchQuery='',archiveMatchMode='all',archiveMatchLimit=40,archiveMatchMonths=[];
const archiveSeasonFor=date=>Number(date.slice(0,4))-(Number(date.slice(5,7))<7);
async function loadMatchArchiveContext(){
 if(!MatchArchiveIndex)MatchArchiveIndex=await load('match-archive/index.json');
 if(!['today','replays','leagues','cups','international','sources'].includes(state.view))return {matches:[]};
 const month=state.date.slice(0,7),meta=MatchArchiveIndex.months[month];let data=meta?await load(meta.file):{matches:[]};
 archiveMatchMonths=archiveMatchMonths.filter(x=>x!==month).concat(month);while(archiveMatchMonths.length>6)cache.delete('match-archive/'+archiveMatchMonths.shift()+'.json');
 let year=state.archiveYear??archiveSeasonFor(state.date),seasonMeta=MatchArchiveIndex.seasons[year];
 let brief=state.view==='replays'&&seasonMeta?await load(seasonMeta.file):null;
 return {...data,seasonBrief:brief,seasonMeta,year};
}
function archiveMatchFor(m){return context.archive?.matches.find(x=>same(x,m))}
function archiveMatchRows(){let rows=(context.archive?.seasonBrief?.matches||[]).filter(m=>m.date<=state.date);if(archiveMatchMode!=='all')rows=rows.filter(m=>m.replayLevel===archiveMatchMode);let q=archiveMatchQuery.toLowerCase();if(q)rows=rows.filter(m=>(n(m.home)+' '+n(m.away)+' '+m.home+' '+m.away+' '+translateComp(m.competition)).toLowerCase().includes(q));return rows}
function matchArchiveView(){
 const d=context.archive||{},meta=d.seasonMeta,year=d.year??archiveSeasonFor(state.date),all=d.seasonBrief?.matches||[],rows=archiveMatchRows(),pending=all.filter(m=>m.date>state.date).length;
 return `<section class="match-archive-hero"><span class="eyebrow">SEASON BY SEASON · REAL MATCH RECORDS</span><h2>한 시즌의 중요한 밤들을,<br>빠짐없이 따라가다.</h2><p>컵 토너먼트 · 주요 구단 · 시즌 막판 · 대한민국과 주요 국가대표 대회</p></section><div class="archive-match-controls"><label>시즌 <select id="archiveMatchSeason">${Object.keys(MatchArchiveIndex.seasons).map(y=>`<option value="${y}" ${+y===+year?'selected':''}>${y}/${String(+y+1).slice(-2)}</option>`).join('')}</select></label><button class="primary" data-goto="${+year===1955?'1956-01-01':year+'-07-01'}">이 시즌의 시작으로 ↗</button><label>기록 종류 <select id="archiveMatchMode"><option value="all" ${archiveMatchMode==='all'?'selected':''}>모든 주요 경기</option><option value="events" ${archiveMatchMode==='events'?'selected':''}>사건 기록 재생 가능</option><option value="result" ${archiveMatchMode==='result'?'selected':''}>결과 기록 · 시각 자료 없음</option></select></label></div><div class="edition-stats"><span><b>${(meta?.count||0).toLocaleString()}</b> 시즌 주요 경기</span><span><b>${(meta?.events||0).toLocaleString()}</b> 실제 득점·사건 기록 재생</span><span><b>${(meta?.resultOnly||0).toLocaleString()}</b> 결과만 확인되는 경기</span></div><p class="archive-match-note">7월~다음 해 6월을 한 시즌으로 묶습니다. 1955/56과 2026/27은 일부 기간입니다. 주요 구단 경기, 컵 토너먼트, 시즌 막판과 주요 A매치가 선정 대상이며 100경기로 잘라내지 않습니다. 분 단위 자료가 없는 경기는 ‘결과 기록’으로 구분합니다. ${meta?.below100Events?'<b>이 시즌은 시각을 확인한 사건 기록이 100경기 미만입니다. 빈 장면이나 득점 시각을 만들어 채우지 않았습니다.</b>':''}</p><label class="archive-search"><span>⌕</span><input id="archiveMatchSearch" type="search" value="${esc(archiveMatchQuery)}" placeholder="팀·국가·대회 검색" aria-label="주요 경기 검색"></label><div id="archiveMatchResults">${archiveMatchResultsHTML()}</div>${pending?`<div class="archive-future">◈ 이 시즌의 이후 기록 ${pending.toLocaleString()}경기는 날짜가 지나면 목록에 나타납니다. 미래 토너먼트 참가 팀과 결과는 표시하지 않습니다.</div>`:''}<details class="archive-season-coverage"><summary>모든 시즌의 실제 재생 가능 경기 수 확인</summary><div class="table-wrap"><table><thead><tr><th>시즌</th><th>주요 경기</th><th>사건 재생</th><th>결과 기록</th></tr></thead><tbody>${Object.entries(MatchArchiveIndex.seasons).map(([y,v])=>`<tr><td>${y}/${String(+y+1).slice(-2)}</td><td>${v.count.toLocaleString()}</td><td>${v.events.toLocaleString()}${v.below100Events?' · 자료 부족':''}</td><td>${v.resultOnly.toLocaleString()}</td></tr>`).join('')}</tbody></table></div></details>`;
}
function archiveMatchResultsHTML(){const rows=archiveMatchRows();return `<p class="note">현재 날짜까지 ${rows.length.toLocaleString()}경기 · 결과를 표시하지 않는 탐색 목록입니다.</p><div class="archive-match-list">${rows.slice(0,archiveMatchLimit).map(m=>`<article><time>${m.date}</time><div><b>${esc(n(m.home))} <span>vs</span> ${esc(n(m.away))}</b><small>${esc(translateComp(m.competition))} · ${esc(m.reasons.join(' · '))}</small></div><button class="text-button" data-archive-match="${m.id}" data-archive-date="${m.date}">${m.replayLevel==='events'?'그날의 중계로':'그날의 결과 기록'} ↗</button></article>`).join('')||'<div class="edition-empty">선택한 날짜까지 이 조건으로 공개할 경기가 없습니다.</div>'}</div>${rows.length>archiveMatchLimit?'<button class="show-more" id="moreArchiveMatches">주요 경기 더 보기 ↓</button>':''}`}
function archiveLineupsHTML(m){if(!m.lineups?.length&&!m.tournamentSquads?.length)return '';let rows=m.lineups||m.tournamentSquads;return `<details class="archive-lineups"><summary>${m.lineups?.length?'확인된 선발·벤치 명단':'대회 등록 명단 · 이 경기 선발은 미확인'} <small>득점·교체 결과는 숨김</small></summary>${[[m.home,m.homeId],[m.away,m.awayId]].map(([team,id])=>`<section><h4>${esc(n(team))}</h4>${rows.filter(p=>p.team===team||(id!==undefined&&p.teamId!==undefined&&String(p.teamId)===String(id))).map(p=>`<div><span>${p.number&&p.number!=='0'?esc(p.number):'—'}</span><b>${esc(koreanPerson(p.name))}</b><small>${p.role==='starting_lineup'?'선발':p.role==='substitutes'?'벤치':'등록 선수'}${p.captain?' · 주장':''}</small></div>`).join('')}</section>`).join('')}<p class="note">경기·대회 기록의 명단입니다. 실제 명단 발표 시각은 별도로 확인되지 않았습니다.</p></details>`}
function archiveEvidenceHTML(m){return `<div class="archive-replay-evidence"><b>${m.replayLevel==='result'?'결과 기록 · 분 단위 사건 미확보':'실제 기록에 기반한 한국어 재구성 중계'}</b><p>${/without-added/.test(m.eventPrecision||'')?'원문이 추가시간 구분 기호를 제공하지 않습니다. 원문 분 표기를 그대로 재생하며 추가시간의 정확한 순서는 복원하지 않습니다.':'자료에 없는 슈팅·점유율·인터뷰·관중 반응을 만들지 않습니다.'}</p>${m.kickoffUtc?'<p>UEFA 제공 킥오프: '+esc(m.kickoffUtc.replace('T',' ').replace('Z',' UTC'))+' · 과거 시각의 정밀도는 별도 검증되지 않았습니다.</p>':''}${archiveLineupsHTML(m)}<a class="source-link" href="${esc(m.source||m.sources?.[0]||'https://github.com/martj42/international_results')}" target="_blank" rel="noopener">사건·명단 근거 자료 ↗</a></div>`}
function completeArchiveRecord(m){const keys=[E.key(m)];for(const d of [...Object.values(context.leagues||{}),context.intl,context.cup])for(const x of d?.matches||[])if(same(x,m))keys.push(E.key(x));state.watched=[...new Set([...state.watched,...keys])];save()}
function openResultRecord(m){stopDays();stopLive();live=null;const known=done(m);$('#replayBody').innerHTML=`<div class="stadium-head"><div><span class="live-indicator">경기 결과 기록</span><span>${m.date} · ${esc(translateComp(m.competition||m.comp||''))}</span></div><button id="exitLive" aria-label="경기 기록 닫기">×</button></div><div class="stadium-board"><p>시간별 사건 기록 미확보</p><div class="stadium-score"><div>${crestHTML(m.home,{size:'large'})}<h2>${esc(n(m.home))}</h2></div><strong id="recordScore">${known?m.hg+' : '+m.ag:'VS'}</strong><div>${crestHTML(m.away,{size:'large'})}<h2>${esc(n(m.away))}</h2></div></div></div><div class="result-record-body"><h3>이 경기의 실제 종료 결과를 확인할 수 있습니다.</h3><p>득점·카드의 분 단위 자료가 없어 경기 중 스코어나 장면을 재현하지 않습니다. 결과 공개는 실제 중계를 본 것과 구분되는 기록 열람입니다.</p>${known?'<p class="note">이미 공개한 경기입니다.</p>':'<button class="primary" id="revealArchiveResult">실제 종료 결과 공개</button>'}${m.pens&&known?'<p>승부차기 '+m.pens.join('–')+'</p>':''}${archiveEvidenceHTML({...m,replayLevel:'result'})}</div>`;$('#replayModal').showModal();$('#revealArchiveResult')?.addEventListener('click',()=>{completeArchiveRecord(m);$('#recordScore').textContent=m.hg+' : '+m.ag;$('#revealArchiveResult').replaceWith(Object.assign(document.createElement('p'),{textContent:'실제 종료 결과를 공개했습니다.'}));render()})}
async function enterArchivedMatch(id,date){state.date=date;state.cup='';await refresh();let m=context.archive?.matches.find(x=>x.id===id);if(m)openReplay(m);else toast('해당 경기 자료를 불러오지 못했습니다.')}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.archiveMatch)enterArchivedMatch(b.dataset.archiveMatch,b.dataset.archiveDate);if(b.id==='moreArchiveMatches'){archiveMatchLimit+=40;$('#archiveMatchResults').innerHTML=archiveMatchResultsHTML()}});
document.addEventListener('change',e=>{if(e.target.id==='archiveMatchSeason'){state.archiveYear=+e.target.value;archiveMatchLimit=40;refresh()}if(e.target.id==='archiveMatchMode'){archiveMatchMode=e.target.value;archiveMatchLimit=40;render()}});
document.addEventListener('input',e=>{if(e.target.id==='archiveMatchSearch'){archiveMatchQuery=e.target.value;archiveMatchLimit=40;$('#archiveMatchResults').innerHTML=archiveMatchResultsHTML()}});
function standingsRuleNote(lg,rows){const changes=E.adjustmentsFor(state.league,lg.season,state.date,state.closed),rule=E.rulesFor(state.league,lg.season),names={'head-to-head':'동률 팀 간 경기가 모두 끝난 경우 상대전적 → 전체 득실차','goal-average':'승점 → 골 평균','goal-difference':'승점 → 득실차 → 다득점','goals-for':'승점 → 다득점 → 득실차','wins':'승점 → 승리 수 → 득실차'};return `<div class="archive-match-note"><b>이 시즌에 적용하는 순위 규칙</b><span>${names[rule.sort]||'기본 승점·득실 정렬'}${state.league==='france'&&[1973,1974,1975].includes(lg.season)?' · 당시 보너스 승점 적용':''}</span>${changes.length?'<ul>'+changes.map(a=>'<li>'+a.date+' · '+esc(a.title)+' · '+a.points+'점 <a class="source-link" href="'+esc(a.source)+'" target="_blank" rel="noopener">근거 ↗</a></li>').join('')+'</ul>':''}<p>확인된 공식 결정은 발표일을 마감한 뒤 반영합니다. 같은 사건의 항소 결과는 이전 처분을 대체하고, 별도 사건은 합산합니다. 모든 행정 처분이 수록된 것은 아닙니다. ${rows.some(r=>r.tieUnresolved)?'완전히 가릴 근거가 없는 동률은 공동 순위로 표시합니다.':''}${rows.some(r=>r.titlePlayoffRequired)?'우승 동률은 별도 결정전이 필요합니다.':''}</p></div>`}
